"""Demo: the collapse of the Moebius integers to the sign function."""
from __future__ import annotations
from typing import Tuple

def value(x: float, y: float) -> float:
    return y * (2.0 * x - 1.0)

def embed(n: int) -> Tuple[float, float]:
    if n == 0:
        raise ValueError("nonzero integers only")
    return (0.5 + 1.0 / (2.0 * n), float(abs(n)))

def sign_int(n: int) -> int:
    return (n > 0) - (n < 0)

def main() -> None:
    image = set()
    for n in [-100, -6, -3, -2, -1, 1, 2, 3, 6, 100]:
        v = value(*embed(n))
        image.add(round(v))
        assert abs(v - sign_int(n)) < 1e-9
        print(f"n={n:+4d}  value={v:+.3f}  sign={sign_int(n):+d}")
    print("image over Z:", sorted(image), "(only two points => collapse)")
    print("value(embed(1)) == value(embed(2)):",
          abs(value(*embed(1)) - value(*embed(2))) < 1e-12, "=> not injective")

if __name__ == "__main__":
    main()

"""Demo: the twist involution acts as exact negation on values (a Z/2 grading)."""
from __future__ import annotations
from typing import Tuple

def value(x: float, y: float) -> float:
    return y * (2.0 * x - 1.0)

def twist(x: float, y: float) -> Tuple[float, float]:
    return (1.0 - x, y)

def main() -> None:
    for (x, y) in [(0.2, 3.0), (0.75, -1.5), (0.5, 4.0), (0.9, 2.0)]:
        tx, ty = twist(x, y)
        v, tv = value(x, y), value(tx, ty)
        ttx, tty = twist(tx, ty)
        assert abs(tv + v) < 1e-12            # negation
        assert (abs(ttx - x) < 1e-12 and abs(tty - y) < 1e-12)  # involution
        print(f"z=({x},{y})  phi={v:+.2f}  phi(twist)={tv:+.2f}  fixed={abs(x-0.5)<1e-12}")
    print("twist negates values, squares to identity, fixes x = 1/2.")

if __name__ == "__main__":
    main()

"""Demo: phi descends to the quotient and is surjective onto R."""
from __future__ import annotations
from typing import Tuple

def value(x: float, y: float) -> float:
    return y * (2.0 * x - 1.0)

def glue_partner(x: float, y: float) -> Tuple[float, float]:
    if x == 0.0: return (1.0, -y)
    if x == 1.0: return (0.0, -y)
    return (x, y)

def preimage(r: float) -> Tuple[float, float]:
    return (1.0, r) if r >= 0.0 else (0.0, -r)

def main() -> None:
    for y in (-3.0, 0.0, 2.5, 7.0):
        xp, yp = glue_partner(0.0, y)
        assert abs(value(0.0, y) - value(xp, yp)) < 1e-12
    print("well-defined across the gluing: OK")
    for r in (-4.2, 0.0, 3.14159):
        x, y = preimage(r)
        assert abs(value(x, y) - r) < 1e-12
    print("surjective onto R: OK")

if __name__ == "__main__":
    main()

